fun FlowContent.money(cents: Long, code: String = "EUR") {
    val fmt = NumberFormat.getCurrencyInstance(Locale.GERMANY).apply {
        currency = Currency.getInstance(code)
    }
    span(classes = "money") { +fmt.format(cents / 100.0) }
}

